/**
 * The `fuzzystrmatch` extension. `levenshtein` compares edit distance. `daitchMokotoff` needs version 1.2 and PostgreSQL 16.
 *
 * Generated by scripts/ext-generate.ts. Do not edit.
 * `minPostgres` for the base methods is 15. A feature
 * a declared version lacks fails with OKM1812.
 */

import type { Fragment } from "../ops/fragment.js";
import { fnDistance, fnEqualsArg } from "./call.js";
import { extension, type Extension, type ExtensionOptions } from "./index.js";
import { assertExtFeature } from "./feature.js";

/** `fuzzystrmatch` plus the methods the naming overlay selected. */
export type Fuzzystrmatch = Extension & {
  /**
   * `levenshtein(column, value) = distance`.
   *
   * @param value - Text to compare
   * @param distance - Edit distance the function must return
   * @returns A where fragment
   */
  levenshtein(value: string, distance: number): Fragment;
  /**
   * `daitch_mokotoff(column) = daitch_mokotoff(value)`. Needs fuzzystrmatch 1.2 and PostgreSQL 16.
   *
   * @param value - Text to compare
   * @returns A where fragment
   */
  daitchMokotoff(value: string): Fragment;
};

/**
 * Declares `fuzzystrmatch`.
 *
 * @param options - Schema and version pin
 * @returns The extension object and its methods
 */
export function fuzzystrmatch(options: ExtensionOptions = {}): Fuzzystrmatch {
  const declared = extension("fuzzystrmatch", options);
  const schema = declared.schema;
  return {
    ...declared,
    levenshtein(value: string, distance: number): Fragment {
      return fnDistance(schema, "levenshtein", value, distance);
    },
    daitchMokotoff(value: string): Fragment {
      assertExtFeature(options.version, "daitch_mokotoff", {
        name: "fuzzystrmatch",
        extension: "1.2",
        postgres: 16,
      });
      return fnEqualsArg(schema, "daitch_mokotoff", value);
    },
  };
}
